    [Fact] public async Task FailureReleasesReservationWithoutPaying() { var x=await CreateAttempt(); var before=await Financial(x.SessionId); await fixture.CreatePaymentLifecycleService().FailAsync(x.Tenant,x.AttemptId); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Declined,after.Status); Assert.Equal(before.Paid,after.Paid); Assert.Equal(before.Reserved-x.Amount,after.Reserved); }
    [Fact] public async Task CancellationReleasesReservationWithoutPaying() { var x=await CreateAttempt(); var before=await Financial(x.SessionId); await fixture.CreatePaymentLifecycleService().CancelAsync(x.Tenant,x.AttemptId); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Cancelled,after.Status); Assert.Equal(before.Paid,after.Paid); Assert.Equal(before.Reserved-x.Amount,after.Reserved); }
    [Fact] public async Task ExpirationReleasesReservationWithoutPaying() { var x=await CreateAttempt(); var before=await Financial(x.SessionId); await fixture.CreatePaymentLifecycleService().ExpireAsync(x.Tenant,x.AttemptId); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Expired,after.Status); Assert.Equal(before.Paid,after.Paid); Assert.Equal(before.Reserved-x.Amount,after.Reserved); }
    [Fact] public async Task UnknownKeepsReservationAndResolvesToApproved() { var x=await CreateAttempt(); var before=await Financial(x.SessionId); var svc=fixture.CreatePaymentLifecycleService(); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); var unknown=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Unknown,unknown.Status); Assert.Equal(before.Reserved,unknown.Reserved); await svc.ResolveUnknownSuccessAsync(x.Tenant,x.AttemptId); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Approved,after.Status); Assert.Equal(before.Reserved-x.Amount,after.Reserved); Assert.Equal(before.Paid+x.Amount,after.Paid); }
    [Fact] public async Task UnknownCanResolveToDeclinedAndReleaseReservation() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); var before=await Financial(x.SessionId); await svc.ResolveUnknownFailureAsync(x.Tenant,x.AttemptId); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Declined,after.Status); Assert.Equal(before.Reserved-x.Amount,after.Reserved); Assert.Equal(before.Paid,after.Paid); }
    [Fact] public async Task RepeatedFailureReleasesReservationOnce() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.FailAsync(x.Tenant,x.AttemptId); var first=await Financial(x.SessionId); await svc.FailAsync(x.Tenant,x.AttemptId); var second=await Financial(x.SessionId); Assert.Equal(first,second); Assert.Equal(0m,second.Reserved); }
    [Fact] public async Task EmployeeWithoutConfirmCashPermissionIsRejected() { var x=await CreateAttempt(); var token=await fixture.CreateUserTokenAsync(x.Tenant); var r=await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{x.AttemptId}/confirm-cash",new{},token,Guid.NewGuid()); Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode); var after=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Created,after.Status); Assert.Equal(x.Amount,after.Reserved); Assert.Equal(0m,after.Paid); }
    [Fact] public async Task ApprovedAttemptCannotBeCancelled() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.SucceedAsync(x.Tenant,x.AttemptId); var before=await Detailed(x); await Assert.ThrowsAsync<InvalidOperationException>(()=>svc.CancelAsync(x.Tenant,x.AttemptId)); var after=await Detailed(x); Assert.Equal(before,after); }
