    [Fact] public async Task RepeatedMarkUnknownKeepsReservation() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); var first=await Financial(x.SessionId); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); var second=await Financial(x.SessionId); Assert.Equal(first,second); Assert.Equal(PaymentAttemptStatus.Unknown,second.Status); }
    [Fact] public async Task UnknownAllocationCannotBeReservedAgain() { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,10m); var p=await CreatePlan(c); var created=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p.PlanId,allocationIds=new[]{p.AllocationId},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); using var j=JsonDocument.Parse(await created.Content.ReadAsStringAsync()); var id=j.RootElement.GetProperty("attemptId").GetGuid(); var tenant=await TenantId(c.SessionId); await fixture.CreatePaymentLifecycleService().MarkUnknownAsync(tenant,id); var retry=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p.PlanId,allocationIds=new[]{p.AllocationId},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); Assert.Equal(HttpStatusCode.Conflict,retry.StatusCode); }
    [Fact] public async Task ApprovedAttemptRejectsFailExpireAndUnknown() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.SucceedAsync(x.Tenant,x.AttemptId); var before=await Financial(x.SessionId); await Assert.ThrowsAsync<InvalidOperationException>(()=>svc.FailAsync(x.Tenant,x.AttemptId)); await Assert.ThrowsAsync<InvalidOperationException>(()=>svc.ExpireAsync(x.Tenant,x.AttemptId)); await Assert.ThrowsAsync<InvalidOperationException>(()=>svc.MarkUnknownAsync(x.Tenant,x.AttemptId)); Assert.Equal(before,await Financial(x.SessionId)); }
    [Fact] public async Task PartialSettlementDoesNotMarkSessionPaid() { var x=await CreatePartialAttempt(); await using(var beforeDb=fixture.CreateDbContext()){ var before=await beforeDb.Set<TableSession>().AsNoTracking().SingleAsync(a=>a.Id==x.SessionId); var allocation=await beforeDb.Set<PaymentPlanAllocation>().AsNoTracking().SingleAsync(a=>a.Id==x.AllocationId); Assert.Equal(100m,before.TotalAmount); Assert.Equal(0m,before.PaidAmount); Assert.Equal(40m,before.ReservedAmount); Assert.Equal(40m,allocation.Amount); Assert.Equal(40m,x.Amount); } var svc=fixture.CreatePaymentLifecycleService(); await svc.SucceedAsync(x.Tenant,x.AttemptId); await using var db=fixture.CreateDbContext(); var s=await db.Set<TableSession>().AsNoTracking().SingleAsync(a=>a.Id==x.SessionId); var attempt=await db.Set<PaymentAttempt>().AsNoTracking().SingleAsync(a=>a.Id==x.AttemptId); Assert.Equal(PaymentAttemptStatus.Approved,attempt.Status); Assert.Equal(100m,s.TotalAmount); Assert.Equal(40m,s.PaidAmount); Assert.Equal(0m,s.ReservedAmount); Assert.Equal("partially_paid",s.Status); Assert.NotEqual("paid",s.Status); Assert.NotEqual("closed",s.Status); }
    [Fact] public async Task ReservationDoesNotCountAsPaid() { var x=await CreateAttempt(); await using var db=fixture.CreateDbContext(); var s=await db.Set<TableSession>().AsNoTracking().SingleAsync(a=>a.Id==x.SessionId); Assert.Equal(s.TotalAmount,s.PaidAmount+s.ReservedAmount); Assert.Equal(0m,s.PaidAmount); Assert.NotEqual("paid",s.Status); Assert.NotEqual("closed",s.Status); }
    [Fact] public async Task MultipleAttemptsSettleIndependently() { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,100m); var r=await fixture.PostWithIdempotencyAsync("api/v1/table-device/session/payment-plan",new{sessionId=c.SessionId,mode="equal_split",partCount=2},c.Device.AccessToken,Guid.NewGuid()); r.EnsureSuccessStatusCode(); using var j=JsonDocument.Parse(await r.Content.ReadAsStringAsync()); var a=j.RootElement.GetProperty("allocations")[0].GetProperty("allocationId").GetGuid(); var b=j.RootElement.GetProperty("allocations")[1].GetProperty("allocationId").GetGuid(); var pa=j.RootElement.GetProperty("planId").GetGuid(); var ra=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=pa,allocationIds=new[]{a},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); var rb=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=pa,allocationIds=new[]{b},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); ra.EnsureSuccessStatusCode(); rb.EnsureSuccessStatusCode(); using var ja=JsonDocument.Parse(await ra.Content.ReadAsStringAsync()); using var jb=JsonDocument.Parse(await rb.Content.ReadAsStringAsync()); var svc=fixture.CreatePaymentLifecycleService(); var tenant=await TenantId(c.SessionId); await svc.SucceedAsync(tenant,ja.RootElement.GetProperty("attemptId").GetGuid()); var mid=await Financial(c.SessionId); Assert.Equal(50m,mid.Paid); Assert.Equal(50m,mid.Reserved); await svc.SucceedAsync(tenant,jb.RootElement.GetProperty("attemptId").GetGuid()); var end=await Financial(c.SessionId); Assert.Equal(100m,end.Paid); Assert.Equal(0m,end.Reserved); }
    [Fact] public async Task UnknownThenDeclinedAllocationCanBeReservedAgain() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); await svc.ResolveUnknownFailureAsync(x.Tenant,x.AttemptId); var retry=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=x.SessionId,paymentPlanId=x.PlanId,allocationIds=new[]{x.AllocationId},paymentMethod="cash"},x.AccessToken,Guid.NewGuid()); Assert.Equal(HttpStatusCode.Created,retry.StatusCode); await using var db=fixture.CreateDbContext(); Assert.Equal(2,await db.Set<PaymentAttemptAllocation>().CountAsync(a=>a.PaymentPlanAllocationId==x.AllocationId)); }
