    [Fact]
    public async Task AuthorizedEmployeeCanConfirmCashAndMoveReservationToPaid()
    {
        var context = await fixture.CreateOpenSessionAsync();
        await SetTotal(context.SessionId, 10m);
        var plan = await CreatePlan(context);
        var created = await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts", new { tableSessionId = context.SessionId, paymentPlanId = plan.PlanId, allocationIds = new[] { plan.AllocationId }, paymentMethod = "cash" }, context.Device.AccessToken, Guid.NewGuid());
        Assert.Equal(HttpStatusCode.Created, created.StatusCode);
        using var body = JsonDocument.Parse(await created.Content.ReadAsStringAsync()); var attemptId = body.RootElement.GetProperty("attemptId").GetGuid();
        var employee = await fixture.CreateUserTokenAsync(await TenantId(context.SessionId), "payments.confirm_cash");
        var confirmed = await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{attemptId}/confirm-cash", new { }, employee, Guid.NewGuid());
        Assert.Equal(HttpStatusCode.OK, confirmed.StatusCode);
        await using var db = fixture.CreateDbContext();
        var attempt = await db.Set<PaymentAttempt>().SingleAsync(x => x.Id == attemptId); var session = await db.Set<TableSession>().SingleAsync(x => x.Id == context.SessionId);
        Assert.Equal(PaymentAttemptStatus.Approved, attempt.Status); Assert.Equal(10m, session.PaidAmount); Assert.Equal(0m, session.ReservedAmount); Assert.Equal("paid", session.Status);
    }

    [Fact]
    public async Task DuplicateCashConfirmationIsIdempotent()
    {
        var context = await fixture.CreateOpenSessionAsync(); await SetTotal(context.SessionId, 10m); var plan = await CreatePlan(context);
        var created = await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts", new { tableSessionId = context.SessionId, paymentPlanId = plan.PlanId, allocationIds = new[] { plan.AllocationId }, paymentMethod = "cash" }, context.Device.AccessToken, Guid.NewGuid());
        using var body = JsonDocument.Parse(await created.Content.ReadAsStringAsync()); var attemptId = body.RootElement.GetProperty("attemptId").GetGuid(); var employee = await fixture.CreateUserTokenAsync(await TenantId(context.SessionId), "payments.confirm_cash");
        var first = await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{attemptId}/confirm-cash", new { }, employee, Guid.NewGuid()); var second = await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{attemptId}/confirm-cash", new { }, employee, Guid.NewGuid());
        Assert.Equal(HttpStatusCode.OK, first.StatusCode); Assert.Equal(HttpStatusCode.OK, second.StatusCode);
        await using var db = fixture.CreateDbContext(); var session = await db.Set<TableSession>().SingleAsync(x => x.Id == context.SessionId); Assert.Equal(10m, session.PaidAmount); Assert.Equal(0m, session.ReservedAmount);
    }

