    [Fact] public async Task FailureReleasesOnlyItsOwnReservation() { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,100m); var r=await fixture.PostWithIdempotencyAsync("api/v1/table-device/session/payment-plan",new{sessionId=c.SessionId,mode="equal_split",partCount=2},c.Device.AccessToken,Guid.NewGuid()); using var j=JsonDocument.Parse(await r.Content.ReadAsStringAsync()); var ids=j.RootElement.GetProperty("allocations").EnumerateArray().Select(x=>x.GetProperty("allocationId").GetGuid()).ToArray(); var p=j.RootElement.GetProperty("planId").GetGuid(); var a=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p,allocationIds=new[]{ids[0]},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); var b=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p,allocationIds=new[]{ids[1]},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); using var ja=JsonDocument.Parse(await a.Content.ReadAsStringAsync()); var svc=fixture.CreatePaymentLifecycleService(); await svc.FailAsync(await TenantId(c.SessionId),ja.RootElement.GetProperty("attemptId").GetGuid()); var f=await Financial(c.SessionId); Assert.Equal(50m,f.Reserved); }
    [Fact] public async Task InvalidLifecycleTransitionsPreservePersistedState() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.SucceedAsync(x.Tenant,x.AttemptId); var before=await Detailed(x); foreach(var action in new Func<Task>[] { ()=>svc.FailAsync(x.Tenant,x.AttemptId), ()=>svc.ExpireAsync(x.Tenant,x.AttemptId), ()=>svc.MarkUnknownAsync(x.Tenant,x.AttemptId), ()=>svc.CancelAsync(x.Tenant,x.AttemptId) }) await Assert.ThrowsAsync<InvalidOperationException>(action); Assert.Equal(before,await Detailed(x)); }
    [Fact] public async Task ForeignTenantCashAttemptIsNotDisclosed() { var a=await fixture.CreateOpenSessionAsync(); var b=await CreateAttempt(); var employee=await fixture.CreateUserTokenAsync(await TenantId(a.SessionId),"payments.confirm_cash"); var before=await Financial(b.SessionId); var r=await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{b.AttemptId}/confirm-cash",new{},employee,Guid.NewGuid()); Assert.Equal(HttpStatusCode.NotFound,r.StatusCode); Assert.Equal(before,await Financial(b.SessionId)); }
    [Fact] public async Task ConcurrentSuccessSameAttemptAppliesFinancialEffectOnce() { var x=await CreateAttempt(); var tenant=x.Tenant; var tasks=Enumerable.Range(0,2).Select(_=>Task.Run(async()=>{ await using var db=fixture.CreateDbContext(); await new PaymentAttemptLifecycleService(db).SucceedAsync(tenant,x.AttemptId); })).ToArray(); await Task.WhenAll(tasks); var f=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Approved,f.Status); Assert.Equal(x.Amount,f.Paid); Assert.Equal(0m,f.Reserved); }
    [Fact] public async Task ConcurrentSuccessVsFailureHasSingleTerminalOutcome() { var x=await CreateAttempt(); var tenant=x.Tenant; var tasks=new[]{Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).SucceedAsync(tenant,x.AttemptId);}catch(InvalidOperationException){}}),Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).FailAsync(tenant,x.AttemptId);}catch(InvalidOperationException){}})}; await Task.WhenAll(tasks); var f=await Financial(x.SessionId); Assert.Contains(f.Status,new[]{PaymentAttemptStatus.Approved,PaymentAttemptStatus.Declined}); Assert.True(f.Reserved>=0); Assert.True(f.Paid==0m||f.Paid==x.Amount); if(f.Status==PaymentAttemptStatus.Approved) Assert.Equal(x.Amount,f.Paid); else Assert.Equal(0m,f.Paid); Assert.Equal(0m,f.Reserved); }
    [Fact] public async Task ConcurrentSuccessVsCancelHasSingleTerminalOutcome() { var x=await CreateAttempt(); var tenant=x.Tenant; var tasks=new[]{Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).SucceedAsync(tenant,x.AttemptId);}catch(InvalidOperationException){}}),Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).CancelAsync(tenant,x.AttemptId);}catch(InvalidOperationException){}})}; await Task.WhenAll(tasks); var f=await Financial(x.SessionId); Assert.Contains(f.Status,new[]{PaymentAttemptStatus.Approved,PaymentAttemptStatus.Cancelled}); Assert.Equal(0m,f.Reserved); Assert.Equal(f.Status==PaymentAttemptStatus.Approved?x.Amount:0m,f.Paid); }
    [Fact] public async Task ConcurrentDuplicateCashConfirmationPaysOnce() { var x=await CreateAttempt(); var token=await fixture.CreateUserTokenAsync(x.Tenant,"payments.confirm_cash"); var tasks=Enumerable.Range(0,2).Select(_=>fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{x.AttemptId}/confirm-cash",new{},token,Guid.NewGuid())).ToArray(); var responses=await Task.WhenAll(tasks); Assert.All(responses,r=>Assert.True(r.IsSuccessStatusCode||r.StatusCode==HttpStatusCode.Conflict)); var f=await Financial(x.SessionId); Assert.Equal(PaymentAttemptStatus.Approved,f.Status); Assert.Equal(x.Amount,f.Paid); Assert.Equal(0m,f.Reserved); }
    [Fact] public async Task ConcurrentUnknownResolutionHasSingleFinalOutcome() { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); await svc.MarkUnknownAsync(x.Tenant,x.AttemptId); var tasks=new[]{Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).ResolveUnknownSuccessAsync(x.Tenant,x.AttemptId);}catch(InvalidOperationException){}}),Task.Run(async()=>{await using var db=fixture.CreateDbContext(); try{await new PaymentAttemptLifecycleService(db).ResolveUnknownFailureAsync(x.Tenant,x.AttemptId);}catch(InvalidOperationException){}})}; await Task.WhenAll(tasks); var f=await Financial(x.SessionId); Assert.Contains(f.Status,new[]{PaymentAttemptStatus.Approved,PaymentAttemptStatus.Declined}); Assert.Equal(0m,f.Reserved); Assert.Equal(f.Status==PaymentAttemptStatus.Approved?x.Amount:0m,f.Paid); }
    [Fact] public async Task PaymentLifecycleWritesSingleAuditAndOutboxPerTransition() { var x=await CreateAttempt(); await using(var before=fixture.CreateDbContext()){ var created=await before.OutboxMessages.AsNoTracking().Where(e=>e.EstablishmentId==x.Tenant&&e.EventType=="payment-attempt-created.v1").ToListAsync(); Assert.Single(created,e=>PayloadTargetsAttempt(e.Payload,x.AttemptId)); Assert.Single(await before.Set<AuditEntry>().Where(e=>e.AggregateId==x.AttemptId&&e.Action=="payment_attempt.created").ToListAsync()); } var svc=fixture.CreatePaymentLifecycleService(); await svc.SucceedAsync(x.Tenant,x.AttemptId); await svc.SucceedAsync(x.Tenant,x.AttemptId); await using var db=fixture.CreateDbContext(); var approved=await db.OutboxMessages.AsNoTracking().Where(e=>e.EstablishmentId==x.Tenant&&e.EventType=="payment-attempt-approved.v1").ToListAsync(); Assert.Single(approved,e=>PayloadTargetsAttempt(e.Payload,x.AttemptId)); Assert.Single(await db.Set<AuditEntry>().Where(e=>e.AggregateId==x.AttemptId&&e.Action=="payment_attempt.approved").ToListAsync()); }
    private static bool PayloadTargetsAttempt(string payload, Guid id) { using var json=JsonDocument.Parse(payload); return json.RootElement.TryGetProperty("paymentAttemptId",out var value)&&value.GetGuid()==id; }
    private async Task SetTotal(Guid id, decimal total) { await using var db = fixture.CreateDbContext(); var s = await db.Set<TableSession>().SingleAsync(x => x.Id == id); s.TotalAmount = total; s.RemainingAmount = total; await db.SaveChangesAsync(); }
    private sealed record AttemptData(Guid Tenant,Guid SessionId,Guid AttemptId,decimal Amount,Guid PlanId,Guid AllocationId,string AccessToken);
    private async Task<(decimal Reserved, decimal Paid, PaymentAttemptStatus Status)> Financial(Guid id) { await using var db=fixture.CreateDbContext(); var s=await db.Set<TableSession>().AsNoTracking().SingleAsync(x=>x.Id==id); var a=await db.Set<PaymentAttempt>().AsNoTracking().Where(x=>x.TableSessionId==id).OrderByDescending(x=>x.CreatedAt).FirstAsync(); return (s.ReservedAmount,s.PaidAmount,a.Status); }
    private sealed record DetailedSnapshot(PaymentAttemptStatus Status, decimal Amount, decimal Paid, decimal Reserved, string SessionStatus, int Ownership);
    private async Task<DetailedSnapshot> Detailed(AttemptData x) { await using var db=fixture.CreateDbContext(); var s=await db.Set<TableSession>().AsNoTracking().SingleAsync(a=>a.Id==x.SessionId); var a=await db.Set<PaymentAttempt>().AsNoTracking().SingleAsync(a=>a.Id==x.AttemptId); var own=await db.Set<PaymentAttemptAllocation>().AsNoTracking().CountAsync(a=>a.PaymentAttemptId==x.AttemptId); return new(a.Status,a.Amount,s.PaidAmount,s.ReservedAmount,s.Status,own); }
    [Theory]
    [InlineData("pix")]
    [InlineData("credit")]
    [InlineData("debit")]
    public async Task NonCashAttemptCannotUseConfirmCash(string method) { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,10m); var p=await CreatePlan(c); var created=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p.PlanId,allocationIds=new[]{p.AllocationId},paymentMethod=method},c.Device.AccessToken,Guid.NewGuid()); using var j=JsonDocument.Parse(await created.Content.ReadAsStringAsync()); var id=j.RootElement.GetProperty("attemptId").GetGuid(); var before=await Financial(c.SessionId); var token=await fixture.CreateUserTokenAsync(await TenantId(c.SessionId),"payments.confirm_cash"); var r=await fixture.PostWithIdempotencyAsync($"api/v1/payments/attempts/{id}/confirm-cash",new{},token,Guid.NewGuid()); Assert.Equal(HttpStatusCode.Conflict,r.StatusCode); Assert.Equal(before,await Financial(c.SessionId)); }
    [Theory]
    [InlineData("declined")]
    [InlineData("cancelled")]
    [InlineData("expired")]
    public async Task ReleasedAllocationCanBeReservedAgain(string state) { var x=await CreateAttempt(); var svc=fixture.CreatePaymentLifecycleService(); if(state=="declined") await svc.FailAsync(x.Tenant,x.AttemptId); else if(state=="cancelled") await svc.CancelAsync(x.Tenant,x.AttemptId); else await svc.ExpireAsync(x.Tenant,x.AttemptId); var retry=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=x.SessionId,paymentPlanId=x.PlanId,allocationIds=new[]{x.AllocationId},paymentMethod="cash"},x.AccessToken,Guid.NewGuid()); Assert.Equal(HttpStatusCode.Created,retry.StatusCode); }
    private async Task<AttemptData> CreateAttempt() { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,10m); var p=await CreatePlan(c); var r=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new{tableSessionId=c.SessionId,paymentPlanId=p.PlanId,allocationIds=new[]{p.AllocationId},paymentMethod="cash"},c.Device.AccessToken,Guid.NewGuid()); r.EnsureSuccessStatusCode(); using var j=JsonDocument.Parse(await r.Content.ReadAsStringAsync()); var id=j.RootElement.GetProperty("attemptId").GetGuid(); return new(await TenantId(c.SessionId),c.SessionId,id,j.RootElement.GetProperty("amount").GetDecimal(),p.PlanId,p.AllocationId,c.Device.AccessToken); }
    private async Task<AttemptData> CreatePartialAttempt() { var c=await fixture.CreateOpenSessionAsync(); await SetTotal(c.SessionId,100m); var r=await fixture.PostWithIdempotencyAsync("api/v1/table-device/session/payment-plan",new { sessionId=c.SessionId, mode="custom_amount", amount=40m }, c.Device.AccessToken, Guid.NewGuid()); r.EnsureSuccessStatusCode(); using var p=JsonDocument.Parse(await r.Content.ReadAsStringAsync()); var planId=p.RootElement.GetProperty("planId").GetGuid(); var allocationId=p.RootElement.GetProperty("allocations")[0].GetProperty("allocationId").GetGuid(); var a=await fixture.PostWithIdempotencyAsync("api/v1/table-device/payments/attempts",new { tableSessionId=c.SessionId, paymentPlanId=planId, allocationIds=new[]{allocationId}, paymentMethod="cash" }, c.Device.AccessToken, Guid.NewGuid()); a.EnsureSuccessStatusCode(); using var j=JsonDocument.Parse(await a.Content.ReadAsStringAsync()); var id=j.RootElement.GetProperty("attemptId").GetGuid(); return new(await TenantId(c.SessionId),c.SessionId,id,j.RootElement.GetProperty("amount").GetDecimal(),planId,allocationId,c.Device.AccessToken); }
    private async Task<Guid> TenantId(Guid id) { await using var db = fixture.CreateDbContext(); return await db.Set<TableSession>().Where(x => x.Id == id).Select(x => x.EstablishmentId).SingleAsync(); }
    private async Task<(Guid PlanId, Guid AllocationId)> CreatePlan(Phase1ApiFixture.OpenSessionContext c) { var r = await fixture.PostWithIdempotencyAsync("api/v1/table-device/session/payment-plan", new { sessionId = c.SessionId, mode = "total" }, c.Device.AccessToken, Guid.NewGuid()); r.EnsureSuccessStatusCode(); using var j = JsonDocument.Parse(await r.Content.ReadAsStringAsync()); return (j.RootElement.GetProperty("planId").GetGuid(), j.RootElement.GetProperty("allocations")[0].GetProperty("allocationId").GetGuid()); }
